"use client"

import { useEffect, useRef } from "react"
import Image from "next/image"

export default function ImageScroller() {
  const scrollerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const scroller = scrollerRef.current
    if (!scroller) return

    let animationId: NodeJS.Timeout | null = null

    const animate = () => {
      scroller.scrollLeft += 1
      // Reset to beginning when reaching end for seamless loop
      if (scroller.scrollLeft >= scroller.scrollWidth - scroller.clientWidth - 50) {
        scroller.scrollLeft = 0
      }
      animationId = setTimeout(animate, 30)
    }

    animationId = setTimeout(animate, 30)

    return () => {
      if (animationId) clearTimeout(animationId)
    }
  }, [])

  const images = [
    { id: 1, alt: "Moment 1", src: "/mom1.jpeg" },
    { id: 2, alt: "Moment 2", src: "/mom2.jpeg" },
    { id: 3, alt: "Moment 3", src: "/mom3.jpeg" },
    { id: 4, alt: "Moment 4", src: "/mom4.jpeg" },
    { id: 5, alt: "Moment 5", src: "/mom5.jpeg" },
    { id: 6, alt: "Moment 6", src: "/mom6.jpeg" },
    { id: 7, alt: "Moment 7", src: "/mom7.jpeg" },
    { id: 8, alt: "Moment 8", src: "/mom8.jpeg" },
  ]

  return (
    <section className="w-full py-16 bg-gray-100 relative overflow-hidden">
      {/* Blurred background */}
      <div className="absolute inset-0 opacity-10">
        <Image
          src="/mom1.jpeg"
          alt="background blur"
          fill
          unoptimized
          className="object-cover blur-3xl"
        />
      </div>
      
      <div className="max-w-7xl mx-auto px-4 relative z-10">
        <h2 className="text-4xl font-bold mb-8 text-gray-800">Moments From Past Events</h2>

        <div ref={scrollerRef} className="flex gap-6 overflow-x-hidden pb-4">
          {images.map((img) => (
            <div key={img.id} className="flex-shrink-0">
              <div className="relative w-80 h-60 rounded-lg overflow-hidden shadow-lg hover:shadow-2xl transition-shadow">
                <Image
                  src={img.src}
                  alt={img.alt}
                  fill
                  unoptimized
                  className="object-cover"
                />
              </div>
            </div>
          ))}
          {images.map((img) => (
            <div key={`duplicate-${img.id}`} className="flex-shrink-0">
              <div className="relative w-80 h-60 rounded-lg overflow-hidden shadow-lg hover:shadow-2xl transition-shadow">
                <Image
                  src={img.src}
                  alt={`${img.alt} (duplicate)`}
                  fill
                  unoptimized
                  className="object-cover"
                />
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}
